// ─── File: SsrfDefenseDemo.java ───
package com.bank.ssrf;

import java.net.*;
import java.util.*;
import java.util.logging.*;

public class SsrfDefenseDemo {
    private static final Logger log = Logger.getLogger(SsrfDefenseDemo.class.getName());
    static final String BANK_NAME = "National Bank of India";

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        ch.setLevel(Level.ALL);
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        SafeUrlFetcher fetcher = new SafeUrlFetcher(
            Set.of("api.partner.example", "hooks.partner.example"), Set.of("https"));

        // Allowlisted public host -> accepted (would be fetched via egress proxy).
        try {
            fetcher.validate("https://api.partner.example/callback");
            log.info("Allowed: https://api.partner.example/callback (on allowlist, public)");
        } catch (SsrfBlockedException e) {
            log.severe("Unexpected block: " + e.getMessage());
        }

        // Cloud metadata endpoint -> blocked (link-local 169.254.0.0/16).
        try {
            fetcher.validate("http://169.254.169.254/latest/meta-data/iam/security-credentials/");
        } catch (SsrfBlockedException e) {
            log.severe("Blocked metadata SSRF: " + e.getMessage());
        }

        // Internal private IP -> blocked (10.0.0.0/8) and not on allowlist.
        try {
            fetcher.validate("http://10.0.0.5/internal-admin");
        } catch (SsrfBlockedException e) {
            log.warning("Blocked internal SSRF: " + e.getMessage());
        }

        // Non-allowlisted host -> blocked even if public.
        try {
            fetcher.validate("https://evil.example/steal");
        } catch (SsrfBlockedException e) {
            log.warning("Blocked non-allowlisted host: " + e.getMessage());
        }
    }
}

