class SsrfBlockedException extends RuntimeException {
    SsrfBlockedException(String m) { super(m); }
}

// ─── Would be in SafeUrlFetcher.java ───
class SafeUrlFetcher {
    private final Set<String> allowedHosts;
    private final Set<String> allowedSchemes;
    SafeUrlFetcher(Set<String> allowedHosts, Set<String> allowedSchemes) {
        this.allowedHosts = allowedHosts; this.allowedSchemes = allowedSchemes;
    }

    // Validate BEFORE fetching; re-validate after any redirect in production.
    void validate(String rawUrl) {
        URI uri;
        try { uri = URI.create(rawUrl); } catch (Exception e) {
            throw new SsrfBlockedException("malformed URL");
        }
        String scheme = uri.getScheme();
        if (scheme == null || !allowedSchemes.contains(scheme.toLowerCase()))
            throw new SsrfBlockedException("scheme not allowed: " + scheme);

        String host = uri.getHost();
        if (host == null) throw new SsrfBlockedException("no host");
        if (!allowedHosts.contains(host))
            throw new SsrfBlockedException("host not on allowlist: " + host);

        // Resolve and check the IP — defend against DNS rebinding / private targets.
        InetAddress addr;
        try { addr = resolve(host); } catch (Exception e) {
            throw new SsrfBlockedException("cannot resolve host: " + host);
        }
        if (isInternal(addr))
            throw new SsrfBlockedException("resolves to internal/reserved IP: " + addr.getHostAddress());
        // Safe: connect to the pinned address through the egress proxy (omitted).
    }

    // Allows the demo to simulate resolution without real DNS.
    InetAddress resolve(String host) throws UnknownHostException {
        switch (host) {
            case "169.254.169.254": return InetAddress.getByName("169.254.169.254");
            case "10.0.0.5":        return InetAddress.getByName("10.0.0.5");
            default:                return InetAddress.getByName("93.184.216.34"); // public
        }
    }

    private boolean isInternal(InetAddress a) {
        return a.isLoopbackAddress() || a.isAnyLocalAddress()
            || a.isLinkLocalAddress()   // 169.254.0.0/16 incl. metadata endpoint
            || a.isSiteLocalAddress();  // 10/8, 172.16/12, 192.168/16
    }
}

